"""Email Analyst connector/agent fabric.

The fabric is intentionally capability-oriented: it can load hundreds of adapters
without coupling the Email Analyst to any specific vendor. Only configured adapters
are executed; unconfigured entries remain explicitly unavailable.
"""
from __future__ import annotations

from dataclasses import dataclass, asdict
from typing import Any

@dataclass(frozen=True)
class ToolProfile:
    name: str
    category: str
    open_source: bool
    capabilities: tuple[str, ...]
    status: str = "adapter-ready"

