# Merge the curated base set with the additional ecosystem profiles.
TOOLS = TOOLS + [x for x in EXTRA_TOOLS if x[0] not in {n for n, _ in TOOLS}]

LANES = (
    "ioc-extract", "reputation", "relationship", "timeline", "campaign", "malware", "email", "network", "case", "report", "sandbox-submit", "stix"
)


def connector_fabric() -> dict[str, Any]:
    profiles = []
    for name, category in TOOLS:
        is_oss = name not in NON_OSS_OR_UNCERTAIN
        profiles.append(asdict(ToolProfile(name=name, category=category, open_source=is_oss, capabilities=LANES)))
    oss_count = sum(1 for p in profiles if p["open_source"])
    return {
        "model": "modular-enrichment-fabric",
        "unique_open_source_tools": oss_count,
        "total_catalog_tools": len(TOOLS),
        "connector_capability_lanes": len(LANES),
        "connector_capabilities": len(TOOLS) * len(LANES),
        "configured_connectors": 0,
        "execution_policy": "only configured connectors execute; unavailable connectors are never fabricated",
        "profiles": profiles,
    }


def agent_manifest() -> dict[str, Any]:
    fabric = connector_fabric()
    return {
        "agent": "K4 Email Analyst Agent",
        "mode": "deterministic evidence orchestration",
        "fabric": {
            "tools": fabric["unique_open_source_tools"],
            "capabilities": fabric["connector_capabilities"],
            "status": "adapter-ready",
        },
        "actions": [
            "parse", "normalize", "extract", "score", "correlate", "enrich", "map-frameworks", "prepare-ir", "report"
        ],
        "human_confirmation_required": ["mailbox quarantine", "firewall block", "endpoint isolation", "credential reset", "artifact deletion"],
    }
